using namespace std;
int jumpSearch(const vector<int>& a, int t) {
    int n=a.size(), step=sqrt(n), prev=0;
    while(a[min(step,n)-1]<t){prev=step;step+=sqrt(n);if(prev>=n)return -1;}
    while(a[prev]<t){prev++;if(prev==min(step,n))return -1;}
    return a[prev]==t?prev:-1;
}
